window.CH3={"missions": [{"id": "e1", "en": "Rock Detectives", "zh": "岩石侦探", "art": "rock-a", "page": "130–133", "tier": 1, "skill": "Observe & classify", "skillzh": "观察分类", "intro": "Look closely. Separate what a picture shows from what needs a test.", "introzh": "仔细观察，区分图片能显示的性质与需要测试的性质。", "fact": "Color and visible grains are observation clues. A picture alone cannot tell us hardness.", "factzh": "颜色与可见颗粒是观察线索。单靠图片不能判断硬度。", "share": "What would you test before naming this rock?", "sharezh": "给岩石命名前，你还想测试什么？", "artifact": "Observation notebook", "artifactzh": "观察笔记", "steps": [{"type": "multi", "en": "Which two features can you see in these drawings?", "zh": "这些示意图能直接看出哪两种特征？", "options": ["Color", "How hard a rock is", "Visible grains"], "answers": [0, 2], "min": 2, "hint": "Look for color and grain patterns. 观察颜色与颗粒。", "record": "DRAWING RECORD · 示意观察卡\nA: gray, large grains / 灰色，颗粒较大\nB: pink, large grains / 粉色，颗粒较大\nC: gray, tiny grains / 灰色，颗粒细小"}, {"type": "choice", "en": "Two rocks are the same size. Must they weigh the same?", "zh": "两块岩石大小相同，重量一定相同吗？", "options": ["Yes, always.", "No. We need a balance."], "answer": 1, "hint": "Size does not prove weight. 大小不能证明重量。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["I can observe", "color and grains.", "Hardness needs a test."], "translation": "我能观察颜色和颗粒。硬度需要测试。", "hint": "I can observe color and grains. Hardness needs a test."}]}, {"id": "e2", "en": "Sort It Two Ways", "zh": "换个标准分一分", "art": "rock-b", "page": "132–139", "tier": 1, "skill": "Observe & classify", "skillzh": "观察分类", "intro": "Use the same three rocks twice. Change the rule, then compare the groups.", "introzh": "同三块岩石分两次，改变分类标准再比较分组。", "fact": "A sample can join different groups when the classification rule changes.", "factzh": "分类标准变化时，同一样本可以进入不同组。", "share": "Which rock changed groups? Why?", "sharezh": "哪块岩石换了组？为什么？", "artifact": "Two sorting trays", "artifactzh": "双标准分类盘", "steps": [{"type": "sort", "en": "First, sort by color.", "zh": "先按颜色分组。", "items": [{"id": "A", "en": "Rock A", "zh": "灰色、颗粒明显", "art": "rock-a", "clue": "Record: gray with large visible grains.", "cluezh": "灰色、颗粒明显", "to": "gray"}, {"id": "B", "en": "Rock B", "zh": "粉色、颗粒明显", "art": "rock-b", "clue": "Record: pink with large visible grains.", "cluezh": "粉色、颗粒明显", "to": "pink"}, {"id": "C", "en": "Rock C", "zh": "灰色、颗粒细小", "art": "rock-c", "clue": "Record: gray with tiny grains.", "cluezh": "灰色、颗粒细小", "to": "gray"}], "groups": [{"id": "gray", "en": "Gray", "zh": "灰色"}, {"id": "pink", "en": "Pink", "zh": "粉色"}], "hint": "Read the color in each record. 查看每张记录的颜色。"}, {"type": "sort", "en": "Now sort the same rocks by visible grain size.", "zh": "再按可见颗粒大小分组。", "items": [{"id": "A", "en": "Rock A", "zh": "灰色、颗粒明显", "art": "rock-a", "clue": "Record: gray with large visible grains.", "cluezh": "灰色、颗粒明显", "to": "coarse"}, {"id": "B", "en": "Rock B", "zh": "粉色、颗粒明显", "art": "rock-b", "clue": "Record: pink with large visible grains.", "cluezh": "粉色、颗粒明显", "to": "coarse"}, {"id": "C", "en": "Rock C", "zh": "灰色、颗粒细小", "art": "rock-c", "clue": "Record: gray with tiny grains.", "cluezh": "灰色、颗粒细小", "to": "fine"}], "groups": [{"id": "coarse", "en": "Large visible grains", "zh": "较大颗粒"}, {"id": "fine", "en": "Tiny grains", "zh": "细小颗粒"}], "hint": "A and B have large visible grains. A 与 B 有较大颗粒。"}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Rock A and Rock B", "share a grain-size group,", "but have different colors."], "translation": "岩石 A 和 B 在同一颗粒大小组，但颜色不同。", "hint": "Rock A and Rock B share a grain-size group, but have different colors."}]}, {"id": "e3", "en": "Pieces of Granite", "zh": "花岗岩里的矿物", "art": "granite", "page": "134–136", "tier": 1, "skill": "Observe & classify", "skillzh": "观察分类", "intro": "Read a labeled model of one granite sample. Match its parts to the mineral names.", "introzh": "阅读一块花岗岩样本的标注模型，把组分与矿物名称对应。", "fact": "Granite contains several minerals. Color alone does not identify every mineral in nature.", "factzh": "花岗岩含多种矿物。在自然界中，不能只凭颜色辨认所有矿物。", "share": "Why do we say “this sample” rather than “every rock”?", "sharezh": "为什么说“这个样本”，而不说“所有岩石”？", "artifact": "Granite specimen label", "artifactzh": "花岗岩样本标签", "steps": [{"type": "sort", "en": "Use the sample labels to match the pieces.", "zh": "按本样本标注匹配组分。", "items": [{"id": "white", "en": "White piece", "zh": "白色组分", "art": "feldspar", "clue": "Sample label: white feldspar.", "cluezh": "白色组分", "to": "feldspar"}, {"id": "gray", "en": "Gray piece", "zh": "灰色组分", "art": "quartz", "clue": "Sample label: gray quartz.", "cluezh": "灰色组分", "to": "quartz"}, {"id": "black", "en": "Black piece", "zh": "黑色组分", "art": "mica", "clue": "Sample label: black mica.", "cluezh": "黑色组分", "to": "mica"}], "groups": [{"id": "quartz", "en": "Quartz", "zh": "石英"}, {"id": "mica", "en": "Mica", "zh": "云母"}, {"id": "feldspar", "en": "Feldspar", "zh": "长石"}], "hint": "These are labels for this sample, not a universal color key. 这是本样本标注，不是通用颜色鉴定表。"}, {"type": "choice", "en": "Can one rock contain several minerals?", "zh": "一块岩石可以含多种矿物吗？", "options": ["Yes. This granite is evidence.", "No. A rock has only one mineral."], "answer": 0, "hint": "Count the three labeled parts. 数一数三个标注组分。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["This granite", "contains quartz, feldspar,", "and mica."], "translation": "这块花岗岩含有石英、长石和云母。", "hint": "This granite contains quartz, feldspar, and mica."}]}, {"id": "e4", "en": "Test Before You Tell", "zh": "测试后再判断", "art": "test", "page": "136–139", "tier": 2, "skill": "Test & explain", "skillzh": "测试解释", "intro": "A shiny sample is not always a hard sample. Match each question with useful evidence.", "introzh": "有光泽不等于硬。给每个问题选择合适的证据。", "fact": "Hardness means resistance to scratching. Luster describes how a surface reflects light.", "factzh": "硬度是抗划伤的能力。光泽描述表面反光的样子。", "share": "Why would a photograph not settle a hardness question?", "sharezh": "为什么照片不能回答硬度问题？", "artifact": "Property test card", "artifactzh": "性质测试卡", "steps": [{"type": "sort", "en": "Choose the useful test for each question.", "zh": "给每个问题选择有用的测试。", "items": [{"id": "shine", "en": "Does it shine?", "zh": "观察反光", "art": "quartz", "clue": "Look at the surface under a light.", "cluezh": "观察反光", "to": "light"}, {"id": "scratch", "en": "Can it be scratched?", "zh": "观察划痕", "art": "test", "clue": "Read a controlled scratch-test record.", "cluezh": "观察划痕", "to": "scratch"}], "groups": [{"id": "light", "en": "Light observation", "zh": "灯光观察"}, {"id": "scratch", "en": "Scratch test", "zh": "划痕测试"}], "hint": "Shine and hardness are different properties. 光泽和硬度是不同性质。", "recall": "Revisit earlier evidence · 用学过的方法解决新问题"}, {"type": "choice", "en": "The same tool scratches A, but not B. Which resists this tool better?", "zh": "同一工具划伤 A，但没有划伤 B。哪个更能抵抗这个工具的划伤？", "options": ["Sample A", "Sample B", "The brighter sample"], "answer": 1, "hint": "Use the scratch record, not brightness. 看划痕记录，不看亮度。", "record": "MODEL RECORD · 示例记录\nSame tool and procedure: A — scratched; B — no scratch.\n相同工具和方法：A 有划痕；B 无划痕。"}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Sample B", "resists this tool better", "because it was not scratched."], "translation": "B 更能抵抗这个工具，因为它没有被划伤。", "hint": "Sample B resists this tool better because it was not scratched."}]}, {"id": "e5", "en": "Water in a Crack", "zh": "裂缝里的水", "art": "ice", "page": "140–145", "tier": 2, "skill": "Test & explain", "skillzh": "测试解释", "intro": "Follow a simplified model of water freezing in a rock crack.", "introzh": "跟随岩石裂缝中水结冰的简化模型。", "fact": "Freezing water can widen a crack. Repeated freezing and thawing can help break rock over time.", "factzh": "水结冰可能使裂缝扩大。反复冻融会随时间帮助岩石破碎。", "share": "Would every rock split after one cold night?", "sharezh": "每块岩石都会在一个寒冷夜晚后裂开吗？", "artifact": "Freeze-and-thaw model", "artifactzh": "冻融模型", "steps": [{"type": "order", "en": "Arrange the model events.", "zh": "排列模型中的事件。", "items": [{"id": "water", "en": "Water enters", "zh": "水进入裂缝", "art": "water-crack", "clue": "Water enters an existing crack.", "cluezh": "水进入裂缝", "to": null}, {"id": "ice", "en": "Water freezes", "zh": "水结冰", "art": "ice", "clue": "The water freezes and expands.", "cluezh": "水结冰", "to": null}, {"id": "wider", "en": "Crack may widen", "zh": "裂缝可能扩大", "art": "crack", "clue": "The crack may become wider.", "cluezh": "裂缝可能扩大", "to": null}], "hint": "Water enters → freezes → crack may widen. 进水→结冰→裂缝可能扩大。"}, {"type": "choice", "en": "Does this model prove every rock breaks after one freeze?", "zh": "模型能证明所有岩石结冰一次就破碎吗？", "options": ["Yes. One freeze always breaks a rock.", "No. Change may take repeated cycles."], "answer": 1, "hint": "A model shows a possible process, not a fixed timetable. 模型展示可能的过程，不规定固定时间。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["When water freezes,", "it expands", "and may widen a crack."], "translation": "水结冰会膨胀，可能扩大裂缝。", "hint": "When water freezes, it expands and may widen a crack."}]}, {"id": "e6", "en": "Break or Move?", "zh": "破碎还是搬运", "art": "root-crack", "page": "140–145", "tier": 2, "skill": "Test & explain", "skillzh": "测试解释", "intro": "Follow roots and flowing water. Separate breaking rock from moving pieces.", "introzh": "跟随树根与流水，区分岩石破碎和碎屑搬运。", "fact": "Growing roots can widen cracks. Flowing water can carry loose pieces to a new place.", "factzh": "生长的根能扩大裂缝；流水能把松散碎屑搬到新地方。", "share": "How does this connect with the roots on Plant Island?", "sharezh": "这与植物岛学到的根有什么联系？", "artifact": "Rock change trail", "artifactzh": "岩石变化路线", "steps": [{"type": "sort", "en": "Sort these two recorded events.", "zh": "给这两个记录事件分类。", "items": [{"id": "root", "en": "Growing root", "zh": "根生长", "art": "root-crack", "clue": "A growing root pushes a crack wider.", "cluezh": "根生长", "to": "break"}, {"id": "river", "en": "Flowing stream", "zh": "溪流流动", "art": "stream", "clue": "The stream carries loose pieces downstream.", "cluezh": "溪流流动", "to": "move"}], "groups": [{"id": "break", "en": "Breaks rock apart", "zh": "使岩石破碎"}, {"id": "move", "en": "Moves loose pieces", "zh": "搬运松散碎屑"}], "hint": "Ask: did it break here, or move to a new place? 看是原地破碎还是换了位置。"}, {"type": "choice", "en": "A small stone arrives downstream. Does that prove it broke there?", "zh": "一块小石头来到下游，能证明它在下游破碎吗？", "options": ["Yes.", "No. Water may have carried it."], "answer": 1, "hint": "Location does not tell the whole history. 地点不能说明全部历史。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Roots can widen cracks.", "Moving water can carry", "loose rock pieces."], "translation": "根能扩大裂缝。流水能搬运松散碎屑。", "hint": "Roots can widen cracks. Moving water can carry loose rock pieces."}]}, {"id": "e7", "en": "Inside the Soil", "zh": "土壤里面有什么", "art": "soil", "page": "150–153", "tier": 3, "skill": "Compare evidence", "skillzh": "比较证据", "intro": "Look beneath the surface. Soil is more than tiny pieces of rock.", "introzh": "看向地表下面，土壤不只有细小岩石颗粒。", "fact": "Soil can contain mineral particles, decaying organic matter, water, and air.", "factzh": "土壤可以包含矿物颗粒、腐解有机物、水和空气。", "share": "What do roots take from soil? What do leaves make?", "sharezh": "根从土壤吸收什么？叶片制造什么？", "artifact": "Soil ingredient tray", "artifactzh": "土壤成分盘", "steps": [{"type": "sort", "en": "Match each soil clue to its part.", "zh": "将土壤线索与成分匹配。", "items": [{"id": "grain", "en": "Small grains", "zh": "细小颗粒", "art": "sand", "clue": "Tiny pieces of minerals.", "cluezh": "细小颗粒", "to": "mineral"}, {"id": "leaf", "en": "Decaying leaf", "zh": "腐解叶片", "art": "humus", "clue": "Remains of living things.", "cluezh": "腐解叶片", "to": "organic"}, {"id": "drop", "en": "Water in a space", "zh": "孔隙中的水", "art": "water", "clue": "Liquid water between particles.", "cluezh": "孔隙中的水", "to": "water"}, {"id": "air", "en": "Air in a space", "zh": "孔隙中的空气", "art": "air", "clue": "Air can fill spaces between particles.", "cluezh": "孔隙中的空气", "to": "air"}], "groups": [{"id": "mineral", "en": "Mineral particles", "zh": "矿物颗粒"}, {"id": "organic", "en": "Organic matter", "zh": "有机物"}, {"id": "water", "en": "Water", "zh": "水"}, {"id": "air", "en": "Air", "zh": "空气"}], "hint": "Match each record, including the spaces. 看每张记录，也注意孔隙。", "recall": "Revisit earlier evidence · 用学过的方法解决新问题"}, {"type": "choice", "en": "Which statement connects soil and plant life?", "zh": "哪句话正确连接土壤与植物生活？", "options": ["Roots eat soil as food.", "Roots take in water and minerals; leaves make food using light."], "answer": 1, "hint": "Remember Plant Island: roots absorb; leaves make food. 回想植物岛：根吸收，叶制造食物。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Soil contains", "mineral particles and organic matter,", "with water and air in its spaces."], "translation": "土壤含矿物颗粒与有机物，孔隙中有水和空气。", "hint": "Soil contains mineral particles and organic matter, with water and air in its spaces."}]}, {"id": "e8", "en": "A Fair Soil Test", "zh": "公平的土壤试验", "art": "lab", "page": "154–159", "tier": 3, "skill": "Compare evidence", "skillzh": "比较证据", "intro": "Prepare two tests that differ only in the soil sample.", "introzh": "准备两组只改变土样的对比试验。", "fact": "A fair comparison keeps the water amount, soil volume, container, and observation time the same.", "factzh": "公平比较要保持水量、土样体积、容器与观察时间相同。", "share": "What would go wrong if one cup received twice as much water?", "sharezh": "如果一杯加了两倍的水，比较会有什么问题？", "artifact": "Fair-test plan", "artifactzh": "公平试验方案", "steps": [{"type": "sort", "en": "What changes, and what stays the same?", "zh": "什么改变，什么保持相同？", "items": [{"id": "sample", "en": "Soil sample", "zh": "土样", "art": "soil", "clue": "Compare sample A with sample B.", "cluezh": "土样", "to": "change"}, {"id": "water", "en": "Added water", "zh": "加入的水量", "art": "water", "clue": "Add 100 mL to each sample.", "cluezh": "加入的水量", "to": "same"}, {"id": "time", "en": "Observation time", "zh": "观察时间", "art": "clock", "clue": "Read both after one minute.", "cluezh": "观察时间", "to": "same"}, {"id": "cup", "en": "Container and soil volume", "zh": "容器和土样体积", "art": "lab", "clue": "Use matching cups and equal soil volumes.", "cluezh": "容器和土样体积", "to": "same"}], "groups": [{"id": "change", "en": "Change this", "zh": "改变这一项"}, {"id": "same", "en": "Keep the same", "zh": "保持相同"}], "hint": "Change the sample, keep the test conditions the same. 改变土样，保持试验条件一致。"}, {"type": "choice", "en": "A gets 100 mL; B gets 200 mL. Is this a fair comparison?", "zh": "A 加100毫升，B 加200毫升。比较公平吗？", "options": ["Yes.", "No. Equalize the water amount first."], "answer": 1, "hint": "Water added must be equal. 加入的水量必须相同。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["To compare soil samples,", "I keep the water amount", "and test conditions the same."], "translation": "比较土样时，我保持水量和试验条件相同。", "hint": "To compare soil samples, I keep the water amount and test conditions the same."}]}, {"id": "e9", "en": "Water Through Soil", "zh": "水怎样穿过土壤", "art": "lab", "page": "154–159", "tier": 3, "skill": "Compare evidence", "skillzh": "比较证据", "intro": "Run three example models. Read the water collected below each cup.", "introzh": "运行三个示例模型，读取每杯下方收集的水量。", "fact": "In this example, A lets more water through in one minute than B or C. The result describes these samples and conditions.", "factzh": "本例中，A 在一分钟内流出的水多于 B 和 C。结论针对这些样本和条件。", "share": "Does less collected water always mean a better soil?", "sharezh": "流出的水越少，土壤就一定越好吗？", "artifact": "Soil test record", "artifactzh": "土壤试验记录", "steps": [{"type": "lab", "en": "Run each sample model and compare the readings.", "zh": "运行三个土样模型，比较读数。", "items": [{"id": "A", "value": 60}, {"id": "B", "value": 35}, {"id": "C", "value": 10}], "hint": "Run all three samples to collect comparable records. 运行三个样本，收集可比较记录。"}, {"type": "choice", "en": "Which sample lets the most water through in one minute?", "zh": "哪个样本一分钟内流出的水最多？", "options": ["Sample C", "Sample A", "Sample B"], "answer": 1, "hint": "Compare 60, 35, and 10 mL. 比较60、35、10毫升。", "record": "EXAMPLE MODEL · 示例模型\nEqual soil volume, matching cups, 100 mL added, read after 1 minute.\n相同土量和杯子，各加100毫升水，1分钟后读数。\nCollected water / 流出的水: A = 60 mL; B = 35 mL; C = 10 mL."}, {"type": "choice", "en": "What can this experiment support?", "zh": "这次试验能支持什么结论？", "options": ["A is best for every plant.", "A lets the most water through under these conditions."], "answer": 1, "hint": "Keep the claim within the evidence. 结论不要超出证据范围。", "record": "EXAMPLE MODEL · 示例模型\nEqual soil volume, matching cups, 100 mL added, read after 1 minute.\n相同土量和杯子，各加100毫升水，1分钟后读数。\nCollected water / 流出的水: A = 60 mL; B = 35 mL; C = 10 mL."}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["In this test,", "sample A lets the most water through", "in one minute."], "translation": "在这次试验中，A 土样一分钟内流出的水最多。", "hint": "In this test, sample A lets the most water through in one minute."}]}, {"id": "e10", "en": "Underground Helpers", "zh": "地下小帮手", "art": "worm", "page": "156–157", "tier": 4, "skill": "Transfer & defend", "skillzh": "迁移论证", "intro": "Follow an earthworm tunnel. Connect animal actions with soil spaces.", "introzh": "跟随蚯蚓通道，把动物活动与土壤孔隙联系起来。", "fact": "Burrowing animals can mix soil and make paths for air and water. An earthworm is not a beetle larva.", "factzh": "掘穴动物能混合土壤，为水和空气形成通道。蚯蚓不是甲虫幼虫。", "share": "How is an earthworm different from the mealworm you studied?", "sharezh": "蚯蚓和学过的面包虫有什么不同？", "artifact": "Tunnel pathway model", "artifactzh": "地下通道模型", "steps": [{"type": "order", "en": "Arrange a possible chain of events.", "zh": "排列一种可能的事件链。", "items": [{"id": "dig", "en": "Animal digs", "zh": "动物挖掘", "art": "worm", "clue": "An animal burrows through the soil.", "cluezh": "动物挖掘", "to": null}, {"id": "space", "en": "A tunnel forms", "zh": "形成通道", "art": "tunnel", "clue": "A connected space forms.", "cluezh": "形成通道", "to": null}, {"id": "flow", "en": "Air and water move", "zh": "空气与水流动", "art": "water", "clue": "Air and water can move through it.", "cluezh": "空气与水流动", "to": null}], "hint": "Digging → tunnel → paths for air and water. 挖掘→通道→空气和水的路径。", "recall": "Revisit earlier evidence · 用学过的方法解决新问题"}, {"type": "choice", "en": "Must an earthworm become a beetle, like a mealworm?", "zh": "蚯蚓也一定像面包虫一样变成甲虫吗？", "options": ["Yes. All worm-shaped animals do.", "No. A similar shape does not mean the same life cycle."], "answer": 1, "hint": "Recall Animal Cove: names and shapes alone are not enough. 回想动物海湾：名称与外形不足以判断。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Burrowing animals", "make tunnels", "that help air and water move through soil."], "translation": "掘穴动物形成通道，帮助空气和水穿过土壤。", "hint": "Burrowing animals make tunnels that help air and water move through soil."}]}, {"id": "e11", "en": "Choose for the Greenhouse", "zh": "为温室选择土样", "art": "greenhouse", "page": "154–159", "tier": 4, "skill": "Transfer & defend", "skillzh": "迁移论证", "intro": "Use the test record and a fictional plant brief. Choose evidence, not a favorite color.", "introzh": "用试验记录和虚构的植物需求卡选土，根据证据而不是喜好。", "fact": "A useful choice depends on the plant and the test conditions. There is no single best soil for every plant.", "factzh": "选择要结合植物需求与试验条件，不存在适合所有植物的唯一最佳土壤。", "share": "What would change if another plant needed faster drainage?", "sharezh": "如果另一株植物需要更快排水，选择会怎样变？", "artifact": "Greenhouse recommendation", "artifactzh": "温室建议书", "steps": [{"type": "choice", "en": "Our model plant needs 30–40 mL collected in this test. Which sample fits?", "zh": "模型植物的要求：本试验流出30–40毫升。哪个样本符合？", "options": ["Sample A: 60 mL", "Sample B: 35 mL", "Sample C: 10 mL"], "answer": 1, "hint": "35 lies between 30 and 40. 35在30与40之间。", "record": "EXAMPLE MODEL · 示例模型\nEqual soil volume, matching cups, 100 mL added, read after 1 minute.\n相同土量和杯子，各加100毫升水，1分钟后读数。\nCollected water / 流出的水: A = 60 mL; B = 35 mL; C = 10 mL.\nFICTIONAL PLANT BRIEF · 虚构需求卡: target 30–40 mL.", "recall": "Revisit earlier evidence · 用学过的方法解决新问题"}, {"type": "multi", "en": "Choose two pieces of evidence for your recommendation.", "zh": "选择支持建议的两条证据。", "options": ["B produced 35 mL in the test.", "B must be best for every plant.", "The model target is 30–40 mL."], "answers": [0, 2], "min": 2, "hint": "Use the measured result and the stated target. 使用试验结果与指定目标。"}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["I choose sample B", "because 35 mL", "fits this model plant’s target."], "translation": "我选择B，因为35毫升符合这个模型植物的目标。", "hint": "I choose sample B because 35 mL fits this model plant’s target."}]}, {"id": "e12", "en": "The Rock Valley Exhibition", "zh": "岩石山谷研究展", "art": "granite", "page": "166–169", "tier": 4, "skill": "Transfer & defend", "skillzh": "迁移论证", "intro": "Review the claims for our research exhibition. Correct mistakes with evidence from the chapter.", "introzh": "检查研究展的说法，用本章证据纠正错误。", "fact": "Strong explanations connect observations, fair tests, and carefully limited conclusions.", "factzh": "有力的解释连接观察、公平试验与范围恰当的结论。", "share": "Which claim would you investigate next, and how?", "sharezh": "接下来你想研究哪个说法？怎样研究？", "artifact": "Rock Valley exhibition", "artifactzh": "岩石山谷研究展", "steps": [{"type": "sort", "en": "Place each claim in the correct display.", "zh": "给各条说法选择正确展板。", "items": [{"id": "shine", "en": "Shiny means hard", "zh": "有光泽就一定硬", "art": "quartz", "clue": "Shine describes reflected light, not scratch resistance.", "cluezh": "有光泽就一定硬", "to": "fix"}, {"id": "soil", "en": "Soil has several parts", "zh": "土壤有多种成分", "art": "soil", "clue": "Particles, organic matter, water, and air can all occur in soil.", "cluezh": "土壤有多种成分", "to": "keep"}, {"id": "best", "en": "One soil is best for all plants", "zh": "一种土适合所有植物", "art": "greenhouse", "clue": "Different plants can have different requirements.", "cluezh": "一种土适合所有植物", "to": "fix"}], "groups": [{"id": "keep", "en": "Supported", "zh": "有证据支持"}, {"id": "fix", "en": "Needs correction", "zh": "需要修正"}], "hint": "Use a test for hardness; match soil to plant needs. 硬度需测试；选土需看需求。", "recall": "Revisit earlier evidence · 用学过的方法解决新问题"}, {"type": "choice", "en": "A new model plant needs 50–70 mL collected. Which sample now fits?", "zh": "新模型植物要求流出50–70毫升。这次哪个土样符合？", "options": ["Sample B, because we chose it before.", "Sample A, because it produced 60 mL.", "Sample C, because it produced the least."], "answer": 1, "hint": "The evidence is the same, but the target changed. 证据没变，目标改变了。", "record": "EXAMPLE MODEL · 示例模型\nEqual soil volume, matching cups, 100 mL added, read after 1 minute.\n相同土量和杯子，各加100毫升水，1分钟后读数。\nCollected water / 流出的水: A = 60 mL; B = 35 mL; C = 10 mL."}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["When the plant’s needs change,", "my choice may change.", "I use the test record", "to explain why."], "translation": "植物需求改变时，我的选择可能改变。我用试验记录解释原因。", "hint": "When the plant’s needs change, my choice may change. I use the test record to explain why."}]}], "tiers": [{"en": "Look & classify", "zh": "观察与分类", "range": "01–03"}, {"en": "Test & explain", "zh": "测试与解释", "range": "04–06"}, {"en": "Investigate soil", "zh": "探究土壤", "range": "07–09"}, {"en": "Use your evidence", "zh": "综合运用证据", "range": "10–12"}]};
window.CH3.audio={};window.CH3.missions.forEach(m=>{window.CH3.audio[m.id+'-intro']=m.intro;window.CH3.audio[m.id+'-fact']=m.fact;m.steps.forEach((s,i)=>{window.CH3.audio[m.id+'-step'+i]=s.en;if(s.type==='sentence')window.CH3.audio[m.id+'-sentence']=s.parts.join(' ');});});
window.validateEarth=function(a){
 if(a===undefined)return {completed:[],drafts:{},works:{},shared:[]};
 const bad=()=>{throw Error('第三章存档内容无效')};
 if(!a||!Array.isArray(a.completed)||a.completed.length>12||a.completed.some((v,i)=>v!==i)||!a.drafts||typeof a.drafts!=='object'||Array.isArray(a.drafts)||!a.works||typeof a.works!=='object'||Array.isArray(a.works))bad();
 const validStep=(x,s)=>{
  if(!x||typeof x!=='object'||Array.isArray(x))bad();
  const ids=s.items?.map(t=>t.id)||[];
  for(const key of Object.keys(x))if(!['seen','placed','order','selected','prediction','views','bg','hint','checked','tokens','opened'].includes(key))bad();
  for(const key of ['seen','order','opened'])if(x[key]!==undefined&&(!Array.isArray(x[key])||x[key].length>12||x[key].some(v=>!ids.includes(v))||new Set(x[key]).size!==x[key].length))bad();
  if(x.placed!==undefined){if(!x.placed||typeof x.placed!=='object'||Array.isArray(x.placed))bad();for(const [id,g] of Object.entries(x.placed))if(!ids.includes(id)||!s.groups?.some(t=>t.id===g))bad();}
  if(x.selected!==undefined&&(!Array.isArray(x.selected)||new Set(x.selected).size!==x.selected.length||x.selected.some(v=>!Number.isInteger(v)||v<0||v>=(s.type==='population'?8:s.options?.length||0))))bad();
  if(x.tokens!==undefined&&(!Array.isArray(x.tokens)||new Set(x.tokens).size!==x.tokens.length||x.tokens.some(v=>!Number.isInteger(v)||v<0||v>=(s.parts?.length||0))))bad();
  if(x.prediction!==undefined&&!['green','brown','unsure'].includes(x.prediction))bad();
  if(x.bg!==undefined&&!['green','brown'].includes(x.bg))bad();
  if(x.views!==undefined&&(!Array.isArray(x.views)||x.views.length>2||x.views.some(v=>!['green','brown'].includes(v))))bad();
  for(const k of ['hint','checked'])if(x[k]!==undefined&&typeof x[k]!=='boolean')bad();
 };
 for(const collection of ['drafts','works'])for(const [id,d] of Object.entries(a[collection])){
  const m=window.CH3.missions.find(m=>m.id===id);if(!m||!d||!Number.isInteger(d.step)||d.step<0||d.step>=m.steps.length||!d.answers||typeof d.answers!=='object'||Array.isArray(d.answers))bad();
  for(const [idx,x] of Object.entries(d.answers)){if(!/^\d+$/.test(idx)||!m.steps[+idx])bad();validStep(x,m.steps[+idx]);}
 }
 if(a.shared!==undefined&&(!Array.isArray(a.shared)||a.shared.some(x=>!Number.isInteger(x)||!a.completed.includes(x))||new Set(a.shared).size!==a.shared.length))bad();
 return {completed:[...a.completed],drafts:a.drafts,works:a.works,shared:a.shared||[]};
};
